/// A batch subscriber definition that produces replies to publish.
///
/// The batch counterpart of [`PublishingDef`](super::PublishingDef): the handler consumes the
/// whole decoded batch and returns the replies for it, all-or-nothing. Selective per-element
/// outcomes are not available here: a handler needing them publishes manually from a plain batch
/// handler, through a publisher held in the typed application state.
pub trait BatchPublishingDef: MaybeSendSync {
    /// The input kind of one batch element ([`Decoded<T>`](super::Decoded); see
    /// [`BatchDef::Input`](super::BatchDef::Input)). The handler consumes `&[T]`.
    type Input: InputKind;

    /// The tuple of startup-injected parameters ([`Out`](super::Out), ...; `()` when the
    /// signature carries none), resolved like
    /// [`InjectDef::Injections`](super::InjectDef::Injections).
    type Injections;

    /// The broker's typed subscription-scoped context the batch's handler reads by key (`()`
    /// when the handler names none), exactly as on
    /// [`BatchDef::Context`](super::BatchDef::Context): built once per batch from its first
    /// delivery, so a replying batch body reaches the subscription's handles (a reposition
    /// handle, a consumer-group name) the same way a settling one does.
    type Context;

    /// The reply element type; each entry of the returned `Vec` is encoded and published.
    type Reply;

    /// The subscription source this handler binds to (see
    /// [`SubscriberDef::Source`](super::SubscriberDef::Source)).
    type Source;

    /// Builds the subscription source (fresh each call).
    fn source(&self) -> Self::Source;

    /// The name (subject / channel) the replies are published to.
    fn reply_name(&self) -> &str;

    /// The name the mount site wrote for the reply when the reply type's own
    /// `#[outgoing(name = "..")]` declaration overrode it, so startup can report it. `None` where
    /// the two agree or the mount site named nothing.
    fn ignored_reply_name(&self) -> Option<&str> {
        None
    }

    /// The concurrency policy for this subscriber's dispatch loop (how many batches are in
    /// flight at once). The macro fills this in from the `workers(..)` argument; the default is
    /// sequential dispatch.
    fn workers(&self) -> Workers {
        Workers::sequential()
    }

    /// The failure policy for a batch-handler panic and a per-element decode failure. The macro
    /// fills this in from the `on_failure(panic = .., decode = ..)` argument; the default fails
    /// fast on a panic and drops on a decode failure.
    fn failure_policies(&self) -> FailurePolicies {
        FailurePolicies::default()
    }

    /// An optional human description (from the handler's doc comment), for `AsyncAPI`.
    fn description(&self) -> Option<&str> {
        None
    }

    /// The element type's serialized JSON Schema, when it implements [`schemars::JsonSchema`]
    /// and the `asyncapi` feature is on. The macro fills this in; the default omits it.
    #[cfg(ruststream_alloc)]
    fn input_schema(&self) -> Option<String> {
        None
    }

    /// The serialized JSON Schema of the element type's header contract, when one is declared
    /// and the `asyncapi` feature is on. The default omits it.
    #[cfg(ruststream_alloc)]
    fn headers_schema(&self) -> Option<String> {
        None
    }

    /// The messages this handler publishes, for the `AsyncAPI` `send` operations: the reply
    /// message, plus every `Out` slot dictionary entry. The macro fills this in; the default
    /// declares nothing. Called once at registration.
    #[cfg(ruststream_alloc)]
    fn outgoing(&self) -> Vec<OutgoingMessageMetadata> {
        Vec::new()
    }

    /// The element type's [`Message`](crate::MessageInfo) name, when it implements that trait. The
    /// macro fills this in; the default omits it.
    fn message_name(&self) -> Option<&'static str> {
        None
    }

    /// The element type's [`Message`](crate::MessageInfo) description, when it implements that
    /// trait. The macro fills this in; the default omits it.
    fn message_description(&self) -> Option<&'static str> {
        None
    }
}

/// Runs a [`BatchPublishingDef`]'s handler body over an app state of type `S`.
///
/// Split from [`BatchPublishingDef`] so a handler that ignores the app state is generic over `S`
/// (mounts on any app), while one that reads it via [`Context::state`](super::Context::state)
/// implements this only for its declared `S` - the state match is checked at compile time without
/// pinning a single `State` on the def.
pub(crate) trait BatchPublishingCall<S>: BatchPublishingDef {
    /// Runs the handler body on one decoded batch.
    ///
    /// `Ok(replies)` publishes every reply to [`reply_name`](BatchPublishingDef::reply_name) and
    /// acks the batch; `Err(result)` publishes nothing and settles the batch with `result` -
    /// one uniform outcome, or one outcome per element.
    fn call(
        &self,
        batch: &[<Self::Input as InputKind>::Owned],
        injections: &Self::Injections,
        ctx: &mut Context<'_, Self::Context, S>,
    ) -> impl Future<Output = Result<BatchVec<Self::Reply>, BatchResult>> + MaybeSend;
}

/// Builds the registration metadata for a batch publishing definition mounted under `name`.
#[cfg(ruststream_alloc)]
pub(crate) fn batch_publishing_metadata<D: BatchPublishingDef>(
    name: &str,
    def: &D,
) -> HandlerMetadata {
    let mut meta = HandlerMetadata::raw(name.to_owned())
        .with_output_type(any::type_name::<D::Reply>())
        .with_def_details(
            def.description(),
            def.input_schema(),
            def.headers_schema(),
            def.message_name(),
            def.message_description(),
        );
    meta.input_type = <D::Input as InputKind>::input_label();
    meta.deserialized = <D::Input as InputKind>::DESERIALIZED;
    meta.outgoing = def.outgoing();
    meta
}

/// Where a batch handler keeps the replies of one batch that did not go out, until the `.error`
/// closure the context registered has read them. Implemented for the size a mount names: `()` with
/// `alloc`, where the replies wait in a `Vec`, and `BatchSize<N>` without it, where they wait in
/// a buffer of `N` that the call owns. Machinery; never named directly.
#[doc(hidden)]
pub trait ReplyLoss {
    /// What one batch's call holds.
    type Held: MaybeSend;

    /// The room of a call with nothing lost.
    fn held() -> Self::Held;

    /// Hands the replies the refusal lost to the `.error` closure of `reaction`: at once, as the
    /// continuation to run after the batch is acknowledged, or into `held`, for [`react`](Self::react)
    /// to run it once the batch is settled.
    fn lose<Reply>(
        held: &mut Self::Held,
        reaction: Reaction,
        refusal: BatchRefusal,
        name: &str,
        replies: &[Reply],
        encode: impl Fn(&Reply) -> CopiedPayload,
        lent: impl FnOnce(usize, usize) -> CopiedPayload,
    ) -> Option<Continuation>;

    /// Runs the reaction `held` waits with, once the batch is settled.
    fn react(held: &mut Self::Held) -> impl Future<Output = ()> + MaybeSend;
}

#[cfg(ruststream_alloc)]
impl ReplyLoss for () {
    type Held = ();

    fn held() {}

    fn lose<Reply>(
        (): &mut (),
        reaction: Reaction,
        refusal: BatchRefusal,
        name: &str,
        replies: &[Reply],
        encode: impl Fn(&Reply) -> CopiedPayload,
        lent: impl FnOnce(usize, usize) -> CopiedPayload,
    ) -> Option<Continuation> {
        let (err, lost) = refusal.into_lost(name, replies, encode, lent);
        Some(reaction.failed_all(err, lost))
    }

    fn react((): &mut ()) -> impl Future<Output = ()> + MaybeSend {
        use core::future::ready;

        ready(())
    }
}

#[cfg(not(ruststream_alloc))]
impl<const ELEMENTS: usize> ReplyLoss for crate::BatchSize<ELEMENTS> {
    type Held = FailureSlot<ELEMENTS>;

    fn held() -> FailureSlot<ELEMENTS> {
        FailureSlot::new()
    }

    fn lose<Reply>(
        held: &mut FailureSlot<ELEMENTS>,
        reaction: Reaction,
        refusal: BatchRefusal,
        name: &str,
        replies: &[Reply],
        encode: impl Fn(&Reply) -> CopiedPayload,
        lent: impl FnOnce(usize, usize) -> CopiedPayload,
    ) -> Option<Continuation> {
        reaction.failed_all(
            refusal.into_failed::<_, ELEMENTS>(name, replies, encode, lent),
            held,
        );
        None
    }

    fn react(held: &mut FailureSlot<ELEMENTS>) -> impl Future<Output = ()> + MaybeSend {
        held.react()
    }
}

/// The `BatchHandler` built from a [`BatchPublishingDef`]: decode the batch, run the handler,
/// publish the replies through the [`ReplyPublisher`], then ack the batch.
///
/// Elements that fail to decode are nacked individually and never reach the handler. A reply the
/// publisher refuses does not retry the batch: the handler already did its work, so the batch is
/// acknowledged, and the replies from the refused one on are lost and told to the `.error`
/// closure the context registered (with none, a warning names them). With a plain publisher
/// the earlier replies stay published; a `.transactional()` wiring never leaves them half-visible.
#[doc(hidden)]
pub struct BatchPublishingHandler<D: BatchPublishingDef, C, R, PP = PublishIdentity, Size = ()> {
    pub(crate) def: D,
    pub(crate) codec: C,
    pub(crate) publisher: R,
    pub(crate) pipeline: PP,
    pub(crate) injections: D::Injections,
    pub(crate) decode: FailurePolicy,
    /// The broker the reply publisher was paired against, which its replies go to.
    #[cfg(feature = "testing")]
    pub(crate) origin: Origin,
    /// The size the mount named, as the type that sizes what a batch loses.
    pub(crate) size: PhantomData<fn() -> Size>,
}

impl<D: BatchPublishingDef, C, R, PP, Size> fmt::Debug
    for BatchPublishingHandler<D, C, R, PP, Size>
{
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("BatchPublishingHandler")
            .finish_non_exhaustive()
    }
}

impl<Batch, M, D, C, R, PP, S, Size> BatchHandler<Batch, D::Context, S>
    for BatchPublishingHandler<D, C, R, PP, Size>
where
    Batch: BatchSlot<Message = M>,
    M: Settle,
    D: BatchPublishingCall<S>,
    D::Input: DecodeWith<C>,
    D::Injections: MaybeSendSync,
    D::Reply: Serialize + MaybeSendSync,
    D::Context: BuildBatchContext<M> + MaybeSendSync + 'static,
    C: MaybeSendSync,
    R: ReplyPublisher<D::Context>,
    PP: PublishPipeline,
    S: MaybeSendSync,
    Size: ReplyLoss,
{
    type Scratch = BatchVec<<D::Input as InputKind>::Owned>;
    type Taken = BatchVec<M>;

    fn taken(size: NonZeroUsize) -> BatchVec<M> {
        BatchVec::with_room(size.get())
    }

    fn load(taken: &mut BatchVec<M>, slot: &mut Batch) {
        slot.hand_over(taken);
    }

    async fn handle_batch<Host: SendHost<D::Context>>(
        &self,
        batch: &mut BatchVec<M>,
        values: &mut Self::Scratch,
        ctx: &mut Context<'_, D::Context, S>,
        host: &Host,
    ) {
        let subscription = ctx.subscription();
        decode_batch::<M, D::Input, C, D::Context, S, Host>(
            batch,
            values,
            &self.codec,
            self.decode,
            ctx,
            host,
        )
        .await;
        if batch.is_empty() {
            return;
        }
        // The replies a refused publish lost wait here until the batch is settled.
        let mut lost = Size::held();
        // The batch the broker delivered is the batch the handler answers for, whole: the size it
        // was built at is the registration's own, so there is nothing left to split here.
        let mut result = match self.def.call(values, &self.injections, ctx).await {
            Ok(replies) => {
                let name = self.def.reply_name();
                // As on the single-message path: the loop's buffer where the dispatch lent one,
                // and one of this batch's own where it did not.
                let mut own = PayloadBuf::new();
                let encode = ctx.take_encode_buffer().unwrap_or(&mut own);
                let slot = <R::Payload as PayloadForm>::encode_slot(encode);
                let pubcx = PublishContext::new(ctx.name(), ctx.delivery_headers(), ctx.cx_ref());
                let publish =
                    self.publisher
                        .publish_batch(name, &replies, &self.pipeline, &pubcx, slot);
                #[cfg(feature = "testing")]
                let publish = publishing_to(self.origin, publish);
                let sent = publish.await;
                let reaction = ctx.take_reaction_for(HandlerResult::Ack);
                // The replies left and nothing waits on them: the common case ends here.
                if sent.is_ok() && reaction.is_none() {
                    BatchResult::Uniform(HandlerOutcome::ack())
                } else {
                    // The batch is acknowledged either way: the handler already did its work, and
                    // a requeue would run it again for the same elements.
                    let follow = match (sent, reaction) {
                        (Ok(()), reaction) => publish_done(reaction),
                        // The `.error` the context registered is told of every reply.
                        (Err(refusal), Some(reaction)) => {
                            let codec = self.publisher.reply_codec();
                            Size::lose(
                                &mut lost,
                                reaction,
                                refusal,
                                name,
                                &replies,
                                |reply| reply.encoded_with(codec),
                                |addr, len| lent_bytes(encode, addr, len, empty_payload),
                            )
                        }
                        (Err(refusal), None) => {
                            let err = refusal.into_error();
                            warn!(
                                target: "ruststream::dispatch",
                                subscription = %subscription,
                                reply = %name,
                                reply_type = any::type_name::<D::Reply>(),
                                error = %err,
                                "batch reply publish failed; replies lost",
                            );
                            None
                        }
                    };
                    BatchResult::Uniform(follow.map_or_else(HandlerOutcome::ack, |follow| {
                        HandlerOutcome::ack().and_after_boxed(follow)
                    }))
                }
            }
            Err(result) => result,
        };
        values.clear();
        settle_batch(batch, &mut result, subscription, ctx.delivery(), host).await;
        Size::react(&mut lost).await;
    }
}

